   504  /* mrb_gc_unregister() removes the object from GC root. */
   505  MRB_API void
   506  mrb_gc_unregister(mrb_state *mrb, mrb_value obj)
   507  {
   508    mrb_sym root;
   509    mrb_value table;
   510    struct RArray *a;
   511    mrb_int i;
   512
   513    if (mrb_immediate_p(obj)) return;
   514    root = GC_ROOT_SYM;
   515    table = mrb_gv_get(mrb, root);
   516    if (mrb_nil_p(table)) return;
   517    if (!mrb_array_p(table)) {
   518      mrb_gv_set(mrb, root, mrb_nil_value());
   519      return;
   520    }
   521    a = mrb_ary_ptr(table);
   522    mrb_ary_modify(mrb, a);
   523    for (i = 0; i < ARY_LEN(a); i++) {
   524      if (mrb_ptr(ARY_PTR(a)[i]) == mrb_ptr(obj)) {
   525        mrb_int len = ARY_LEN(a)-1;
   526        mrb_value *ptr = ARY_PTR(a);
   527
   528        ARY_SET_LEN(a, len);
   529        memmove(&ptr[i], &ptr[i + 1], (len - i) * sizeof(mrb_value));
   530        break;
   531      }
   532    }
   533  }
